export function getHexagonPoints(cx: number, cy: number, radius: number, flatTop: boolean = false): string {
  const points: string[] = [];
  const offset = flatTop ? 0 : 30;
  for (let i = 0; i < 6; i++) {
    const angle = ((60 * i - offset) * Math.PI) / 180;
    const px = Number((cx + radius * Math.cos(angle)).toFixed(1));
    const py = Number((cy + radius * Math.sin(angle)).toFixed(1));
    points.push(`${px},${py}`);
  }
  return points.join(" ");
}

